def initialize_research(query, depth=None, **_extra):
    import json, os, datetime, time, uuid, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "DeepResearch",
            "endpoint": "initialize-research",
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            return None
        max_rpm = cfg.get("max_requests_per_minute")
        if not isinstance(max_rpm, int) or max_rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
        if recent >= max_rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=max_rpm, window_seconds=60, used=recent)
        return None

    def _gen_id(prefix):
        # ULID-like is unnecessary; just ensure uniqueness within file.
        return prefix + uuid.uuid4().hex

    # Validate inputs
    if query is None or not isinstance(query, str):
        _log("error", "VALIDATION_ERROR", "query must be a string")
        return _err("VALIDATION_ERROR", "query must be a string")
    if query.strip() == "":
        _log("error", "VALIDATION_ERROR", "query must not be empty")
        return _err("VALIDATION_ERROR", "query must not be empty")

    if depth is None:
        depth = 3
    if not isinstance(depth, (int, float)) or isinstance(depth, bool):
        _log("error", "VALIDATION_ERROR", "depth must be a number")
        return _err("VALIDATION_ERROR", "depth must be a number")
    # requested_depth is number, but constraints say 1..10; accept ints/floats, store as int when integral else float
    if depth < 1 or depth > 10:
        _log("error", "VALIDATION_ERROR", "depth must be within [1, 10]")
        return _err("VALIDATION_ERROR", "depth must be within [1, 10]")

    rl = _enforce_rate_limit()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"], {k: v for k, v in rl["error"].items() if k not in ("code", "message")})
        return rl

    sessions = _load("research_sessions.json")
    steps = _load("research_steps.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(steps, list):
        steps = []

    # Concurrency limit: only enforce if configured. Do NOT hardcode.
    cfg = _load("service_limits.json")
    if isinstance(cfg, dict):
        lim = cfg.get("max_concurrent_sessions")
        if isinstance(lim, int) and lim > 0:
            active_statuses = {"initialized", "running", "awaiting_report", "reporting"}
            active = sum(1 for s in sessions if isinstance(s, dict) and s.get("status") in active_statuses)
            if active >= lim:
                err = _err("QUOTA_EXCEEDED", "Concurrent session limit exceeded", limit=lim, active=active)
                _log("error", err["error"]["code"], err["error"]["message"], {"limit": lim, "active": active})
                return err

    # Create session + initial plan step
    now = _now()
    sess_id = "drs_sess_" + uuid.uuid4().hex
    # defaults per schema constraints
    timeout_ms_default_report = 60000
    timeout_ms_default_complete = 180000
    max_steps = 1000

    # if limits file provides defaults, use them only if valid and within constraints
    if isinstance(cfg, dict):
        v = cfg.get("timeout_ms_default_report")
        if isinstance(v, (int, float)) and not isinstance(v, bool) and 1000 <= v <= 600000:
            timeout_ms_default_report = v
        v = cfg.get("timeout_ms_default_complete")
        if isinstance(v, (int, float)) and not isinstance(v, bool) and 1000 <= v <= 1200000:
            timeout_ms_default_complete = v
        v = cfg.get("max_steps_default")
        if isinstance(v, int) and 1 <= v <= 1000:
            max_steps = v

    session_row = {
        "id": sess_id,
        "query": query,
        "requested_depth": depth,
        "current_depth": 0,
        "max_steps": max_steps,
        "steps_executed": 0,
        "status": "initialized",
        "last_error": None,
        "timeout_ms_default_report": timeout_ms_default_report,
        "timeout_ms_default_complete": timeout_ms_default_complete,
        "final_report_id": None,
        "created_at": now,
        "updated_at": now,
        "completed_at": None
    }

    # step_index unique within session; start at 1
    step_id = "drs_step_" + uuid.uuid4().hex
    step_row = {
        "id": step_id,
        "session_id": sess_id,
        "step_index": 1,
        "depth": 1,
        "kind": "plan",
        "status": "pending",
        "input": {"query": query, "requested_depth": depth},
        "output": None,
        "error": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }

    sessions.append(session_row)
    steps.append(step_row)

    try:
        _save("research_sessions.json", sessions)
        _save("research_steps.json", steps)
    except Exception:
        err = _err("CONFLICT", "Failed to persist new session")
        _log("error", err["error"]["code"], err["error"]["message"])
        return err

    resp = {"session": session_row, "sessionId": sess_id}
    _log("ok", None, None, {"session_id": sess_id})
    return resp

def generate_report(sessionId, timeout=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "generate-report",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _rate_limit():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        max_rpm = cfg.get("max_requests_per_minute", 120)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-4000:]:
            try:
                ts = r.get("timestamp")
                if not isinstance(ts, str) or not ts.endswith("Z"):
                    continue
                dt = datetime.datetime.fromisoformat(ts[:-1])
                if dt >= cutoff:
                    recent += 1
            except Exception:
                continue
        if isinstance(max_rpm, int) and max_rpm > 0 and recent >= max_rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _transition(allowed, current, target):
        return target in allowed.get(current, [])

    allowed_session = {
        "initialized": ["running", "cancelled", "failed"],
        "running": ["awaiting_report", "cancelled", "failed"],
        "awaiting_report": ["reporting", "cancelled", "failed"],
        "reporting": ["completed", "failed", "cancelled"],
        "completed": [], "failed": [], "cancelled": []
    }
    allowed_report = {"generating": ["ready", "failed"], "ready": [], "failed": []}

    try:
        if not isinstance(sessionId, str) or not sessionId.strip():
            e = _err("VALIDATION_ERROR", "sessionId must be a non-empty string")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

        rl = _rate_limit()
        if rl:
            _log("error", rl["error"]["code"], rl["error"]["message"])
            return rl

        sessions = _load("research_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        reports = _load("research_reports.json")
        if not isinstance(reports, list):
            reports = []
        sources = _load("sources.json")
        if not isinstance(sources, list):
            sources = []

        session = next((s for s in sessions if s.get("id") == sessionId), None)
        if session is None:
            e = _err("NOT_FOUND", "Session not found", sessionId=sessionId)
            _log("error", e["error"]["code"], e["error"]["message"], meta={"sessionId": sessionId})
            return e

        if timeout is None:
            timeout = session.get("timeout_ms_default_report", 60000)
        if not isinstance(timeout, (int, float)) or isinstance(timeout, bool):
            e = _err("VALIDATION_ERROR", "timeout must be a number")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if timeout < 1000 or timeout > 600000:
            e = _err("VALIDATION_ERROR", "timeout must be within [1000,600000]")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

        # Must be reportable: session at least awaiting_report OR (running allowed by rule for transition to reporting)
        if session.get("status") not in ("awaiting_report", "running", "reporting"):
            e = _err("CONFLICT", "Session is not in a reportable state", status=session.get("status"))
            _log("error", e["error"]["code"], e["error"]["message"], meta={"sessionId": sessionId})
            return e

        # Transition session to reporting (from awaiting_report or running)
        if session.get("status") in ("awaiting_report", "running"):
            if not _transition(allowed_session, session["status"], "reporting"):
                e = _err("INVALID_TRANSITION", "Cannot transition session to reporting", status=session.get("status"))
                _log("error", e["error"]["code"], e["error"]["message"], meta={"sessionId": sessionId})
                return e
            session["status"] = "reporting"
            session["updated_at"] = now

        # Create a new report version
        max_ver = 0
        for r in reports:
            if r.get("session_id") == sessionId:
                try:
                    max_ver = max(max_ver, int(r.get("version", 0)))
                except Exception:
                    pass
        version = max_ver + 1

        rep_id = "rp_" + uuid.uuid4().hex
        rep = {
            "id": rep_id,
            "session_id": sessionId,
            "version": version,
            "status": "generating",
            "timeout_ms": float(timeout),
            "report_markdown": None,
            "summary": None,
            "citations": [],
            "error": None,
            "created_at": now,
            "updated_at": now,
            "generated_at": None
        }
        reports.append(rep)
        _save("research_reports.json", reports)
        _save("research_sessions.json", sessions)

        # "Generate" synchronously within tool call: compile citations from fetched sources
        try:
            fetched_sources = [s for s in sources if s.get("session_id") == sessionId and s.get("retrieval_status") == "fetched"]
            citations = []
            for s in fetched_sources[:20]:
                citations.append({
                    "url": s.get("url"),
                    "title": s.get("title"),
                    "quote": (s.get("content_text") or "")[:240],
                    "source_id": s.get("id")
                })

            report_md = "# Research Report\n\n"
            report_md += f"## Query\n\n{session.get('query','')}\n\n"
            report_md += f"## Completed Depth\n\n{int(float(session.get('current_depth',0)))} / {int(float(session.get('requested_depth',0)))}\n\n"
            report_md += "## Key Sources\n\n"
            if citations:
                for i, c in enumerate(citations, 1):
                    report_md += f"{i}. [{c.get('title') or c.get('url')}]({c.get('url')})\n"
            else:
                report_md += "No fetched sources available.\n"
            report_md += "\n## Notes\n\nGenerated offline from stored session data.\n"

            rep["report_markdown"] = report_md
            rep["summary"] = (f"Report for: {session.get('query','')}"[:300]) if session.get("query") else None
            rep["citations"] = citations
            if not _transition(allowed_report, "generating", "ready"):
                raise ValueError("invalid report transition")
            rep["status"] = "ready"
            rep["generated_at"] = now
            rep["updated_at"] = now

            # Set final_report_id on session
            session["final_report_id"] = rep_id
            session["updated_at"] = now

            _save("research_reports.json", reports)
            _save("research_sessions.json", sessions)

            body = {"report": rep, "session": session}
            _log("ok", meta={"sessionId": sessionId, "reportId": rep_id, "version": version, "status": rep["status"]})
            return body
        except Exception as ex:
            # mark report failed + session failed
            rep["status"] = "failed"
            rep["error"] = str(ex)
            rep["updated_at"] = now
            _save("research_reports.json", reports)

            if _transition(allowed_session, session.get("status"), "failed"):
                session["status"] = "failed"
                session["last_error"] = "report_generation_failed"
                session["updated_at"] = now
                _save("research_sessions.json", sessions)

            e = _err("CONFLICT", "Report generation failed", detail=str(ex))
            _log("error", e["error"]["code"], e["error"]["message"], meta={"sessionId": sessionId, "reportId": rep_id})
            return e

    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error", detail=str(ex))
        _log("error", e["error"]["code"], e["error"]["message"], meta={"detail": str(ex), "sessionId": sessionId})
        return e

def complete_research(query, depth=None, timeout=None, **_extra):
    import json, os, datetime, time, uuid, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now():
        return _now_dt().isoformat() + "Z"

    # ---- request logging + optional rate/quotas (only if those collections exist) ----
    def _append_log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "service": "DeepResearch",
                "endpoint": "complete-research",
                "timestamp": _now(),
                "latency_ms": int((time.time() - t0) * 1000),
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            return None
        max_rpm = cfg.get("max_requests_per_minute")
        if not isinstance(max_rpm, int) or max_rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now_dt() - datetime.timedelta(seconds=60)
        used = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if dt >= cutoff:
                used += 1
        if used >= max_rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=max_rpm, window_seconds=60, used=used)
        return None

    # ---- helpers ----
    def _is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def _gen_id(prefix):
        # Deterministic enough for local store; keep vendor-ish style
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_iso_z(s):
        if not isinstance(s, str) or not s.endswith("Z"):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1])
        except Exception:
            return None

    def _allowed_transition(lifecycle, cur, target):
        transitions = lifecycle.get("transitions", {})
        return target in transitions.get(cur, [])

    def _sha256_text(txt):
        if not isinstance(txt, str):
            return None
        return hashlib.sha256(txt.encode("utf-8")).hexdigest()

    # ---- input validation (must not raise) ----
    try:
        if not isinstance(query, str) or not query.strip():
            rl = _rate_limit_check()
            if rl:
                _append_log("error", rl["error"]["code"], rl["error"]["message"], {"phase": "validate"})
                return rl
            e = _err("VALIDATION_ERROR", "query must be a non-empty string")
            _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "validate"})
            return e

        if depth is None:
            depth = 3
        if timeout is None:
            timeout = 180000

        if not _is_number(depth) or depth < 1 or depth > 10:
            rl = _rate_limit_check()
            if rl:
                _append_log("error", rl["error"]["code"], rl["error"]["message"], {"phase": "validate"})
                return rl
            e = _err("VALIDATION_ERROR", "depth must be a number in [1,10]", min=1, max=10)
            _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "validate"})
            return e

        if not _is_number(timeout) or timeout < 0:
            rl = _rate_limit_check()
            if rl:
                _append_log("error", rl["error"]["code"], rl["error"]["message"], {"phase": "validate"})
                return rl
            e = _err("VALIDATION_ERROR", "timeout must be a non-negative number", min=0)
            _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "validate"})
            return e
    except Exception as ex:
        # unexpected validation failure should be observable but not crash
        e = _err("VALIDATION_ERROR", "invalid input", detail=str(ex))
        _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "validate"})
        return e

    # rate limit (if configured)
    rl = _rate_limit_check()
    if rl:
        _append_log("error", rl["error"]["code"], rl["error"]["message"], {"phase": "rate_limit"})
        return rl

    # Load data
    sessions = _load("research_sessions.json")
    steps = _load("research_steps.json")
    sources = _load("sources.json")
    reports = _load("research_reports.json")

    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(steps, list):
        steps = []
    if not isinstance(sources, list):
        sources = []
    if not isinstance(reports, list):
        reports = []

    # Lifecycle definitions (from schema)
    sess_lifecycle = {
        "field": "status",
        "values": ["initialized", "running", "awaiting_report", "reporting", "completed", "failed", "cancelled"],
        "transitions": {
            "initialized": ["running", "cancelled", "failed"],
            "running": ["awaiting_report", "cancelled", "failed"],
            "awaiting_report": ["reporting", "cancelled", "failed"],
            "reporting": ["completed", "failed", "cancelled"],
            "completed": [],
            "failed": [],
            "cancelled": [],
        },
    }
    step_lifecycle = {
        "field": "status",
        "values": ["pending", "running", "succeeded", "failed", "skipped"],
        "transitions": {"pending": ["running", "skipped"], "running": ["succeeded", "failed"], "succeeded": [], "failed": [], "skipped": []},
    }
    rpt_lifecycle = {"field": "status", "values": ["generating", "ready", "failed"], "transitions": {"generating": ["ready", "failed"], "ready": [], "failed": []}}

    # ---- initialize-research ----
    try:
        now = _now()
        sess_id = "drs_sess_" + uuid.uuid4().hex
        sess_row = {
            "id": sess_id,
            "query": query,
            "requested_depth": float(depth),
            "current_depth": 0.0,
            "max_steps": 1000,
            "steps_executed": 0,
            "status": "initialized",
            "last_error": None,
            "timeout_ms_default_report": 60000.0,
            "timeout_ms_default_complete": 180000.0,
            "final_report_id": None,
            "created_at": now,
            "updated_at": now,
            "completed_at": None,
        }
        # validate session constraints minimally
        if sess_row["requested_depth"] < 1 or sess_row["requested_depth"] > 10:
            e = _err("VALIDATION_ERROR", "requested_depth must be in [1,10]")
            _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "initialize"})
            return e

        sessions.append(sess_row)

        step_id = "drs_step_" + uuid.uuid4().hex
        step_row = {
            "id": step_id,
            "session_id": sess_id,
            "step_index": 1,
            "depth": 1.0,
            "kind": "plan",
            "status": "pending",
            "input": {"query": query, "depth": float(depth)},
            "output": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        steps.append(step_row)

        _save("research_sessions.json", sessions)
        _save("research_steps.json", steps)
    except Exception as ex:
        e = _err("CONFLICT", "failed to initialize research session", detail=str(ex))
        _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "initialize"})
        return e

    # ---- execute steps until awaiting_report or terminal, within complete timeout ----
    deadline = _now_dt() + datetime.timedelta(milliseconds=float(timeout))
    session_idx = len(sessions) - 1  # last appended
    # Ensure session transitions to running at start
    try:
        if sessions[session_idx]["status"] == "initialized":
            if not _allowed_transition(sess_lifecycle, "initialized", "running"):
                e = _err("INVALID_TRANSITION", "Cannot transition session status from initialized to running")
                _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "transition"})
                return e
            sessions[session_idx]["status"] = "running"
            sessions[session_idx]["updated_at"] = _now()
            _save("research_sessions.json", sessions)
    except Exception as ex:
        e = _err("CONFLICT", "failed to update session status", detail=str(ex))
        _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "transition"})
        return e

    def _get_session_steps(sess_id_local):
        return [s for s in steps if s.get("session_id") == sess_id_local]

    def _smallest_pending_step(sess_id_local):
        pend = [s for s in steps if s.get("session_id") == sess_id_local and s.get("status") == "pending"]
        if not pend:
            return None
        pend.sort(key=lambda r: (r.get("step_index", 10**9)))
        return pend[0]

    def _upsert_source(sess_id_local, url, discovered_in_step_id=None, title=None, publisher=None, published_at=None, retrieval_status="discovered", http_status=None, content_text=None, relevance_score=None):
        # unique(session_id,url)
        for src in sources:
            if src.get("session_id") == sess_id_local and src.get("url") == url:
                # update allowed fields + transitions
                cur = src.get("retrieval_status")
                if retrieval_status is not None and retrieval_status != cur:
                    allowed = {"discovered": ["fetched", "fetch_failed"], "fetched": [], "fetch_failed": []}
                    if retrieval_status in allowed.get(cur, []):
                        src["retrieval_status"] = retrieval_status
                    # ignore illegal transitions (real system would likely reject in step tool; here we keep it strict only when explicitly violating)
                    else:
                        return _err("INVALID_TRANSITION", "Illegal retrieval_status transition", from_status=cur, to_status=retrieval_status, source_id=src.get("id"))
                if discovered_in_step_id and src.get("discovered_in_step_id") is None:
                    src["discovered_in_step_id"] = discovered_in_step_id
                if title is not None:
                    src["title"] = title
                if publisher is not None:
                    src["publisher"] = publisher
                if published_at is not None:
                    src["published_at"] = published_at
                if http_status is not None:
                    if not isinstance(http_status, int) or http_status < 100 or http_status > 599:
                        return _err("VALIDATION_ERROR", "http_status must be in [100,599]")
                    src["http_status"] = http_status
                if relevance_score is not None:
                    if not _is_number(relevance_score) or relevance_score < 0 or relevance_score > 1:
                        return _err("VALIDATION_ERROR", "relevance_score must be in [0,1]")
                    src["relevance_score"] = float(relevance_score)
                if content_text is not None:
                    src["content_text"] = content_text
                    src["content_sha256"] = _sha256_text(content_text)
                src["updated_at"] = _now()
                return src
        # insert new
        if not isinstance(url, str) or not url:
            return _err("VALIDATION_ERROR", "url must be a non-empty string")
        now = _now()
        new_src = {
            "id": "drs_src_" + uuid.uuid4().hex,
            "session_id": sess_id_local,
            "discovered_in_step_id": discovered_in_step_id,
            "url": url,
            "title": title,
            "publisher": publisher,
            "published_at": published_at,
            "retrieval_status": retrieval_status or "discovered",
            "http_status": http_status,
            "content_text": content_text,
            "content_sha256": _sha256_text(content_text) if content_text is not None else None,
            "relevance_score": float(relevance_score) if relevance_score is not None else None,
            "created_at": now,
            "updated_at": now,
        }
        sources.append(new_src)
        return new_src

    # very lightweight "engine" to create next steps up to requested_depth
    def _maybe_expand_plan(sess_row_local, plan_step):
        # if we're at a plan step, enqueue search/fetch/extract/synthesize for this depth if not already queued
        sess_id_local = sess_row_local["id"]
        d = int(float(plan_step.get("depth", 1)))
        existing = _get_session_steps(sess_id_local)
        existing_kinds = set((r.get("kind"), int(float(r.get("depth", 1)))) for r in existing)
        # ensure for this depth we have search/fetch/extract/synthesize (simple)
        need = []
        for k in ["search", "fetch", "extract", "synthesize"]:
            if (k, d) not in existing_kinds:
                need.append(k)
        if not need:
            return
        max_idx = 0
        for r in existing:
            si = r.get("step_index")
            if isinstance(si, int) and si > max_idx:
                max_idx = si
        for k in need:
            max_idx += 1
            steps.append(
                {
                    "id": "drs_step_" + uuid.uuid4().hex,
                    "session_id": sess_id_local,
                    "step_index": max_idx,
                    "depth": float(d),
                    "kind": k,
                    "status": "pending",
                    "input": {"query": sess_row_local["query"], "depth": float(d), "kind": k},
                    "output": None,
                    "error": None,
                    "started_at": None,
                    "finished_at": None,
                    "created_at": _now(),
                    "updated_at": _now(),
                }
            )

    def _maybe_next_depth_plan(sess_row_local):
        # if all steps for current depth done, add plan step for next depth
        req = int(float(sess_row_local["requested_depth"]))
        cur_completed_depth = int(float(sess_row_local["current_depth"]))
        next_depth = cur_completed_depth + 1
        if next_depth > req:
            return
        sess_id_local = sess_row_local["id"]
        # check if any pending/running for that depth already exists
        for st in steps:
            if st.get("session_id") == sess_id_local and int(float(st.get("depth", 0) or 0)) == next_depth:
                return
        # create a plan step for next depth
        existing = _get_session_steps(sess_id_local)
        max_idx = max([r.get("step_index", 0) for r in existing if isinstance(r.get("step_index"), int)] or [0])
        steps.append(
            {
                "id": "drs_step_" + uuid.uuid4().hex,
                "session_id": sess_id_local,
                "step_index": max_idx + 1,
                "depth": float(next_depth),
                "kind": "plan",
                "status": "pending",
                "input": {"query": sess_row_local["query"], "depth": float(next_depth)},
                "output": None,
                "error": None,
                "started_at": None,
                "finished_at": None,
                "created_at": _now(),
                "updated_at": _now(),
            }
        )

    def _finalize_depth_progress(sess_row_local):
        sess_id_local = sess_row_local["id"]
        req = int(float(sess_row_local["requested_depth"]))
        # determine highest depth where all steps are terminal (succeeded/failed/skipped) for that depth
        highest = 0
        for d in range(1, req + 1):
            dsteps = [s for s in steps if s.get("session_id") == sess_id_local and int(float(s.get("depth", 0) or 0)) == d]
            if not dsteps:
                break
            if any(s.get("status") in ("pending", "running") for s in dsteps):
                break
            highest = d
        sess_row_local["current_depth"] = float(highest)

    # loop
    try:
        while True:
            if _now_dt() > deadline:
                # mark failed complete timeout
                cur_status = sessions[session_idx]["status"]
                if cur_status not in ("completed", "failed", "cancelled"):
                    if _allowed_transition(sess_lifecycle, cur_status, "failed"):
                        sessions[session_idx]["status"] = "failed"
                        sessions[session_idx]["last_error"] = "complete_timeout"
                        sessions[session_idx]["updated_at"] = _now()
                        _save("research_sessions.json", sessions)
                e = _err("QUOTA_EXCEEDED", "Complete research timeout exceeded", timeout_ms=float(timeout))
                _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "complete_loop"})
                return e

            st = sessions[session_idx]["status"]
            if st in ("completed", "failed", "cancelled", "awaiting_report"):
                break

            # enforce max_steps before executing a step
            if sessions[session_idx].get("steps_executed", 0) >= sessions[session_idx].get("max_steps", 1000):
                # transition to failed as business rule says
                if st not in ("failed", "completed", "cancelled") and _allowed_transition(sess_lifecycle, st, "failed"):
                    sessions[session_idx]["status"] = "failed"
                    sessions[session_idx]["last_error"] = "max_steps_exceeded"
                    sessions[session_idx]["updated_at"] = _now()
                    _save("research_sessions.json", sessions)
                e = _err("QUOTA_EXCEEDED", "Session exceeded max_steps", max_steps=sessions[session_idx].get("max_steps", 1000))
                _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "execute_step"})
                return e

            pending = _smallest_pending_step(sess_id)
            if pending is None:
                # no pending steps: update depth progress and maybe move to awaiting_report
                _finalize_depth_progress(sessions[session_idx])
                sessions[session_idx]["updated_at"] = _now()
                if sessions[session_idx]["current_depth"] >= sessions[session_idx]["requested_depth"]:
                    if _allowed_transition(sess_lifecycle, sessions[session_idx]["status"], "awaiting_report"):
                        sessions[session_idx]["status"] = "awaiting_report"
                else:
                    _maybe_next_depth_plan(sessions[session_idx])
                _save("research_sessions.json", sessions)
                _save("research_steps.json", steps)
                continue

            # mark step running
            if not _allowed_transition(step_lifecycle, pending.get("status"), "running"):
                e = _err("INVALID_TRANSITION", "Cannot start step from current status", step_id=pending.get("id"), status=pending.get("status"))
                _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "execute_step"})
                return e

            pending["status"] = "running"
            pending["started_at"] = _now()
            pending["updated_at"] = _now()
            sessions[session_idx]["steps_executed"] = int(sessions[session_idx].get("steps_executed", 0)) + 1
            sessions[session_idx]["updated_at"] = _now()

            # persist running state + increment exactly once per executed step
            _save("research_steps.json", steps)
            _save("research_sessions.json", sessions)

            # produce output (lightweight, deterministic-ish)
            kind = pending.get("kind")
            d = int(float(pending.get("depth", 1)))
            out = {}
            step_ok = True
            err_txt = None

            if kind == "plan":
                out = {"plan": f"Research plan for depth {d} on: {query}"}
                _maybe_expand_plan(sessions[session_idx], pending)
            elif kind == "search":
                # discover some URLs
                base = "https://example.com/"
                urls = [
                    base + "postgres-logical-replication-lag-monitoring",
                    base + "prometheus-postgres-replication-metrics",
                ]
                discovered = []
                for u in urls:
                    up = _upsert_source(sess_id, u, discovered_in_step_id=pending.get("id"), title="Example", publisher="example.com", retrieval_status="discovered", relevance_score=0.8)
                    if isinstance(up, dict) and "error" in up:
                        step_ok = False
                        err_txt = up["error"]["message"]
                        break
                    discovered.append({"url": u, "source_id": up.get("id")})
                out = {"results": discovered}
            elif kind == "fetch":
                # fetch discovered sources: mark as fetched with content
                sess_sources = [s for s in sources if s.get("session_id") == sess_id]
                fetched = 0
                for src in sess_sources:
                    if src.get("retrieval_status") == "discovered":
                        # simulate possible fetch fail
                        if random.random() < 0.05:
                            res = _upsert_source(sess_id, src.get("url"), retrieval_status="fetch_failed", http_status=429)
                        else:
                            content = f"Content about logical replication lag monitoring. Depth={d}. URL={src.get('url')}"
                            res = _upsert_source(sess_id, src.get("url"), retrieval_status="fetched", http_status=200, content_text=content)
                        if isinstance(res, dict) and "error" in res:
                            step_ok = False
                            err_txt = res["error"]["message"]
                            break
                        fetched += 1
                out = {"fetched": fetched}
            elif kind == "extract":
                # extract facts from fetched sources
                sess_sources = [s for s in sources if s.get("session_id") == sess_id and s.get("retrieval_status") == "fetched"]
                facts = []
                for src in sess_sources[:5]:
                    facts.append(
                        {
                            "source_id": src.get("id"),
                            "url": src.get("url"),
                            "fact": "Monitor pg_stat_replication, pg_replication_slots, and WAL sender/receiver lag; export via postgres_exporter and graph in Grafana.",
                        }
                    )
                out = {"facts": facts}
            elif kind == "synthesize":
                out = {"summary": f"Synthesis for depth {d}: key metrics and alerting strategy for logical replication lag."}
                # after synthesize for this depth, update current_depth
                _finalize_depth_progress(sessions[session_idx])
                if sessions[session_idx]["current_depth"] < d:
                    sessions[session_idx]["current_depth"] = float(d)
            else:
                step_ok = False
                err_txt = "unknown_step_kind"

            # mark step terminal
            if step_ok:
                if not _allowed_transition(step_lifecycle, "running", "succeeded"):
                    e = _err("INVALID_TRANSITION", "Cannot transition step from running to succeeded", step_id=pending.get("id"))
                    _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "execute_step"})
                    return e
                pending["status"] = "succeeded"
                pending["output"] = out
                pending["error"] = None
            else:
                if _allowed_transition(step_lifecycle, "running", "failed"):
                    pending["status"] = "failed"
                    pending["output"] = out if out else None
                    pending["error"] = err_txt or "step_failed"
                else:
                    e = _err("INVALID_TRANSITION", "Cannot transition step from running to failed", step_id=pending.get("id"))
                    _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "execute_step"})
                    return e
                # session fail on step failure
                cur = sessions[session_idx]["status"]
                if cur not in ("failed", "completed", "cancelled") and _allowed_transition(sess_lifecycle, cur, "failed"):
                    sessions[session_idx]["status"] = "failed"
                    sessions[session_idx]["last_error"] = pending["error"]
            pending["finished_at"] = _now()
            pending["updated_at"] = _now()
            sessions[session_idx]["updated_at"] = _now()

            # if no pending remain and depth reached => awaiting_report
            if _smallest_pending_step(sess_id) is None:
                _finalize_depth_progress(sessions[session_idx])
                if sessions[session_idx]["current_depth"] >= sessions[session_idx]["requested_depth"]:
                    cur = sessions[session_idx]["status"]
                    if cur not in ("failed", "completed", "cancelled") and _allowed_transition(sess_lifecycle, cur, "awaiting_report"):
                        sessions[session_idx]["status"] = "awaiting_report"

            _save("research_steps.json", steps)
            _save("sources.json", sources)
            _save("research_sessions.json", sessions)

            # If terminal failure reached, stop
            if sessions[session_idx]["status"] in ("failed", "cancelled", "completed"):
                break

    except Exception as ex:
        # do not raise; mark session failed if possible
        cur = sessions[session_idx].get("status")
        if cur not in ("completed", "failed", "cancelled") and _allowed_transition(sess_lifecycle, cur, "failed"):
            sessions[session_idx]["status"] = "failed"
            sessions[session_idx]["last_error"] = "complete_loop_error"
            sessions[session_idx]["updated_at"] = _now()
            _save("research_sessions.json", sessions)
        e = _err("CONFLICT", "Unexpected error during completion loop", detail=str(ex))
        _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "complete_loop"})
        return e

    # ---- generate-report ----
    try:
        # if session already terminal without awaiting_report, return best available info
        st = sessions[session_idx]["status"]
        if st in ("cancelled", "failed"):
            # no report generation
            body = {
                "sessionId": sess_id,
                "status": st,
                "last_error": sessions[session_idx].get("last_error"),
                "final_report_id": sessions[session_idx].get("final_report_id"),
            }
            _append_log("ok", None, None, {"phase": "done_terminal"})
            return body

        # must be awaiting_report or running; report generation transitions to reporting
        if st not in ("awaiting_report", "running", "reporting"):
            # if completed, return the report
            if st == "completed":
                rpt_id = sessions[session_idx].get("final_report_id")
                rpt = next((r for r in reports if r.get("id") == rpt_id), None)
                _append_log("ok", None, None, {"phase": "already_completed"})
                return {"sessionId": sess_id, "status": "completed", "report": rpt}
            e = _err("INVALID_TRANSITION", "Session is not in a state that can generate a report", status=st)
            _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "generate_report"})
            return e

        # use session default report timeout if caller omitted (caller tool always has timeout for complete; but keep rule)
        report_timeout = sessions[session_idx].get("timeout_ms_default_report", 60000.0)
        if not _is_number(report_timeout):
            report_timeout = 60000.0
        # validate report timeout constraint
        if report_timeout < 1000 or report_timeout > 600000:
            report_timeout = 60000.0

        # transition to reporting if needed
        if sessions[session_idx]["status"] in ("awaiting_report", "running"):
            cur = sessions[session_idx]["status"]
            if not _allowed_transition(sess_lifecycle, cur, "reporting"):
                e = _err("INVALID_TRANSITION", "Cannot transition session to reporting", from_status=cur, to_status="reporting")
                _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "generate_report"})
                return e
            sessions[session_idx]["status"] = "reporting"
            sessions[session_idx]["updated_at"] = _now()
            _save("research_sessions.json", sessions)

        # next version
        sess_versions = [r.get("version") for r in reports if r.get("session_id") == sess_id and isinstance(r.get("version"), int)]
        next_ver = (max(sess_versions) + 1) if sess_versions else 1

        rpt_id = "drs_rpt_" + uuid.uuid4().hex
        rpt_now = _now()
        rpt_row = {
            "id": rpt_id,
            "session_id": sess_id,
            "version": next_ver,
            "status": "generating",
            "timeout_ms": float(report_timeout),
            "report_markdown": None,
            "summary": None,
            "citations": [],
            "error": None,
            "created_at": rpt_now,
            "updated_at": rpt_now,
            "generated_at": None,
        }
        reports.append(rpt_row)
        _save("research_reports.json", reports)

        # generate content using fetched sources as citations
        sess_sources = [s for s in sources if s.get("session_id") == sess_id and s.get("retrieval_status") == "fetched"]
        citations = []
        for s in sess_sources[:10]:
            citations.append({"url": s.get("url"), "title": s.get("title"), "quote": (s.get("content_text") or "")[:160], "source_id": s.get("id")})

        report_md = "# Research Report\n\n"
        report_md += f"## Query\n\n{query}\n\n"
        report_md += "## Findings\n\n- Monitor logical replication lag via exported PostgreSQL metrics.\n- Alert on slot lag growth, apply lag, and subscriber apply delay.\n\n"
        report_md += "## Suggested Metrics & Dashboards\n\n- pg_stat_replication: write/flush/replay lag\n- pg_replication_slots: retained WAL bytes / restart_lsn age\n- subscriber apply delay (logical)\n\n"
        report_md += "## Citations\n\n"
        for i, c in enumerate(citations, 1):
            report_md += f"{i}. {c.get('url')}\n"

        # finalize report lifecycle
        if not _allowed_transition(rpt_lifecycle, "generating", "ready"):
            e = _err("INVALID_TRANSITION", "Cannot transition report to ready")
            _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "generate_report"})
            return e

        rpt_row["status"] = "ready"
        rpt_row["report_markdown"] = report_md
        rpt_row["summary"] = "Best practices and key metrics for monitoring PostgreSQL logical replication lag."
        rpt_row["citations"] = citations
        rpt_row["error"] = None
        rpt_row["generated_at"] = _now()
        rpt_row["updated_at"] = _now()
        _save("research_reports.json", reports)

        # set final_report_id FK on session
        sessions[session_idx]["final_report_id"] = rpt_id
        sessions[session_idx]["updated_at"] = _now()
        _save("research_sessions.json", sessions)

        # ---- transition session to completed only if report is ready ----
        cur = sessions[session_idx]["status"]
        if cur != "completed":
            if rpt_row["status"] == "ready":
                # enforce business rule: final_report_id non-null and references ready report
                if not sessions[session_idx].get("final_report_id"):
                    e = _err("CONFLICT", "Cannot complete session without final_report_id")
                    _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "complete_session"})
                    return e
                # verify FK reference exists and ready
                ref = next((r for r in reports if r.get("id") == sessions[session_idx]["final_report_id"]), None)
                if ref is None or ref.get("status") != "ready":
                    e = _err("INVALID_TRANSITION", "Session can only transition to completed if final report is ready")
                    _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "complete_session"})
                    return e

                if not _allowed_transition(sess_lifecycle, cur, "completed"):
                    e = _err("INVALID_TRANSITION", "Cannot transition session to completed", from_status=cur, to_status="completed")
                    _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "complete_session"})
                    return e
                sessions[session_idx]["status"] = "completed"
                sessions[session_idx]["completed_at"] = _now()
                sessions[session_idx]["updated_at"] = _now()
                _save("research_sessions.json", sessions)

        # return final report
        _append_log("ok", None, None, {"phase": "done"})
        return {
            "sessionId": sess_id,
            "status": sessions[session_idx]["status"],
            "report": rpt_row,
        }

    except Exception as ex:
        # mark report failed if created, session failed if possible
        try:
            # last report for this session in generating state
            rpt = None
            for r in reversed(reports):
                if r.get("session_id") == sess_id and r.get("status") == "generating":
                    rpt = r
                    break
            if rpt is not None and _allowed_transition(rpt_lifecycle, "generating", "failed"):
                rpt["status"] = "failed"
                rpt["error"] = "report_generation_error: " + str(ex)
                rpt["updated_at"] = _now()
                _save("research_reports.json", reports)
        except Exception:
            pass

        cur = sessions[session_idx].get("status")
        if cur not in ("completed", "failed", "cancelled") and _allowed_transition(sess_lifecycle, cur, "failed"):
            sessions[session_idx]["status"] = "failed"
            sessions[session_idx]["last_error"] = "report_generation_error"
            sessions[session_idx]["updated_at"] = _now()
            _save("research_sessions.json", sessions)

        e = _err("CONFLICT", "Unexpected error during report generation", detail=str(ex))
        _append_log("error", e["error"]["code"], e["error"]["message"], {"phase": "generate_report"})
        return e

def list_research_sessions(status=None, query_contains=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            # Support trailing Z
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_from_row(val):
        if not isinstance(val, str) or not val:
            return None
        dt = _parse_dt(val)
        return dt

    def _cursor_decode(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict):
                return None
            u = payload.get("updated_at")
            sid = payload.get("id")
            if not isinstance(u, str) or not isinstance(sid, str):
                return None
            return {"updated_at": u, "id": sid}
        except Exception:
            return None

    def _cursor_encode(updated_at, sid):
        payload = {"updated_at": updated_at, "id": sid}
        raw = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "list-research-sessions"

    # Load sessions
    sessions = _load("research_sessions.json")

    # Validate filters
    allowed_status = {"initialized", "running", "awaiting_report", "reporting", "completed", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "invalid status", field="status", allowed=sorted(list(allowed_status)))

    if query_contains is not None and (not isinstance(query_contains, str)):
        return _err("VALIDATION_ERROR", "query_contains must be a string", field="query_contains")

    dt_after = None
    if created_after is not None:
        dt_after = _parse_dt(created_after)
        if dt_after is None:
            return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string", field="created_after")

    dt_before = None
    if created_before is not None:
        dt_before = _parse_dt(created_before)
        if dt_before is None:
            return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string", field="created_before")

    if limit is None:
        lim = 50
    else:
        if isinstance(limit, bool) or not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        lim = limit
    if lim < 1 or lim > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    cur = _cursor_decode(cursor)
    if cursor is not None and cursor != "" and cur is None:
        return _err("VALIDATION_ERROR", "invalid cursor", field="cursor")

    # Filter
    qsub = query_contains.lower() if isinstance(query_contains, str) and query_contains else None
    out = []
    for s in sessions:
        if status is not None and s.get("status") != status:
            continue
        if qsub:
            q = s.get("query")
            if not isinstance(q, str) or qsub not in q.lower():
                continue
        ca = _dt_from_row(s.get("created_at"))
        if dt_after is not None:
            if ca is None or ca < dt_after:
                continue
        if dt_before is not None:
            if ca is None or ca > dt_before:
                continue
        out.append(s)

    # Order: most recently updated first; tie-breaker by id desc
    def _sort_key(s):
        ua = _dt_from_row(s.get("updated_at"))
        # None updated_at sorts last
        ts = ua.timestamp() if ua is not None else float("-inf")
        return (ts, str(s.get("id", "")))

    out.sort(key=_sort_key, reverse=True)

    # Apply cursor (exclusive) using (updated_at, id)
    if cur is not None:
        cur_dt = _parse_dt(cur["updated_at"])
        if cur_dt is None:
            return _err("VALIDATION_ERROR", "invalid cursor timestamp", field="cursor")
        cur_id = cur["id"]

        def _after_cursor(s):
            ua = _dt_from_row(s.get("updated_at"))
            if ua is None:
                return False
            if ua < cur_dt:
                return False
            if ua > cur_dt:
                return True
            # same updated_at: compare id (desc ordering)
            sid = str(s.get("id", ""))
            return sid < cur_id  # because ordering is desc; ids "after" are smaller

        out = [s for s in out if _after_cursor(s)]

    total = len(out)
    page = out[:lim]
    has_more = total > lim
    next_cursor = None
    if has_more and page:
        last = page[-1]
        if isinstance(last.get("updated_at"), str) and isinstance(last.get("id"), str):
            next_cursor = _cursor_encode(last["updated_at"], last["id"])

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": page,
        "meta": {
            "limit": lim,
            "total_matched": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order_by": "updated_at_desc",
            "latency_ms": latency_ms,
        },
    }

def get_research_session(sessionId, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _REQLOG_FILE = "request_logs.json"
    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, outcome, detail=None):
        logs = _load(_REQLOG_FILE)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "service": "DeepResearch",
            "endpoint": "get-research-session",
            "status": status_code,
            "outcome": outcome,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save(_REQLOG_FILE, logs)

    if sessionId is None or not isinstance(sessionId, str) or not sessionId.strip():
        _log(400, "error", "invalid_sessionId")
        return _err("VALIDATION_ERROR", "sessionId is required and must be a non-empty string")

    sessions = _load("research_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sid = sessionId.strip()
    row = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            row = s
            break

    if row is None:
        _log(404, "error", "not_found")
        return _err("NOT_FOUND", "research session not found", sessionId=sid)

    _log(200, "ok")
    return {"data": row}

def cancel_research_session(sessionId, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _REQLOG_FILE = "request_logs.json"
    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, outcome, detail=None):
        logs = _load(_REQLOG_FILE)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "service": "DeepResearch",
            "endpoint": "cancel-research-session",
            "status": status_code,
            "outcome": outcome,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save(_REQLOG_FILE, logs)

    if sessionId is None or not isinstance(sessionId, str) or not sessionId.strip():
        _log(400, "error", "invalid_sessionId")
        return _err("VALIDATION_ERROR", "sessionId is required and must be a non-empty string")

    if reason is not None and not isinstance(reason, str):
        _log(400, "error", "invalid_reason")
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    sessions = _load("research_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sid = sessionId.strip()
    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sid:
            idx = i
            break

    if idx is None:
        _log(404, "error", "not_found")
        return _err("NOT_FOUND", "research session not found", sessionId=sid)

    session = sessions[idx]
    cur = session.get("status")
    terminal = {"completed", "failed", "cancelled"}
    if cur in terminal:
        _log(409, "error", "terminal_state_conflict")
        return _err("CONFLICT", f"cannot cancel a session in terminal status '{cur}'", sessionId=sid, status=cur)

    # Lifecycle transitions per schema:
    allowed_transitions = {
        "initialized": {"running", "cancelled", "failed"},
        "running": {"awaiting_report", "cancelled", "failed"},
        "awaiting_report": {"reporting", "cancelled", "failed"},
        "reporting": {"completed", "failed", "cancelled"},
        "completed": set(),
        "failed": set(),
        "cancelled": set(),
    }
    if cur not in allowed_transitions or "cancelled" not in allowed_transitions[cur]:
        _log(409, "error", "invalid_transition")
        return _err("INVALID_TRANSITION", f"cannot transition session from '{cur}' to 'cancelled'", sessionId=sid)

    session["status"] = "cancelled"
    if isinstance(reason, str) and reason.strip():
        session["last_error"] = reason.strip()
    session["updated_at"] = _now_iso()
    sessions[idx] = session
    _save("research_sessions.json", sessions)

    _log(200, "ok")
    return {"data": session}

def list_research_steps(sessionId, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _REQLOG_FILE = "request_logs.json"
    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, outcome, detail=None):
        logs = _load(_REQLOG_FILE)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "service": "DeepResearch",
            "endpoint": "list-research-steps",
            "status": status_code,
            "outcome": outcome,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save(_REQLOG_FILE, logs)

    if sessionId is None or not isinstance(sessionId, str) or not sessionId.strip():
        _log(400, "error", "invalid_sessionId")
        return _err("VALIDATION_ERROR", "sessionId is required and must be a non-empty string")

    allowed_status = {"pending", "running", "succeeded", "failed", "skipped"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log(400, "error", "invalid_status")
        return _err("VALIDATION_ERROR", "status must be one of pending,running,succeeded,failed,skipped")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log(400, "error", "invalid_limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

    # Ensure session exists
    sessions = _load("research_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sid = sessionId.strip()
    if not any(isinstance(s, dict) and s.get("id") == sid for s in sessions):
        _log(404, "error", "session_not_found")
        return _err("NOT_FOUND", "research session not found", sessionId=sid)

    # Cursor handling (opaque base64 json: {"i": step_index, "id": id})
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log(400, "error", "invalid_cursor")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_obj = json.loads(raw.decode("utf-8"))
            if not isinstance(cursor_obj, dict) or "i" not in cursor_obj or "id" not in cursor_obj:
                _log(400, "error", "invalid_cursor_shape")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            if not isinstance(cursor_obj["i"], int) or not isinstance(cursor_obj["id"], str):
                _log(400, "error", "invalid_cursor_types")
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except Exception:
            _log(400, "error", "cursor_decode_failed")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    steps = _load("research_steps.json")
    if not isinstance(steps, list):
        steps = []

    filtered = []
    for st in steps:
        if not isinstance(st, dict):
            continue
        if st.get("session_id") != sid:
            continue
        if status is not None and st.get("status") != status:
            continue
        filtered.append(st)

    # Sort by step_index ascending, tiebreaker id ascending
    def _idx(v):
        return v if isinstance(v, int) else 10**18
    filtered.sort(key=lambda x: (_idx(x.get("step_index")), str(x.get("id") or "")))

    # Apply cursor "start after" by (step_index asc, id asc)
    if cursor_obj is not None:
        ci = cursor_obj["i"]
        cid = cursor_obj["id"]
        pageable = []
        for st in filtered:
            si = _idx(st.get("step_index"))
            sid2 = str(st.get("id") or "")
            if (si > ci) or (si == ci and sid2 > cid):
                pageable.append(st)
        filtered = pageable

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"i": int(last.get("step_index")), "id": str(last.get("id") or "")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200, "ok")
    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def list_sources(sessionId, retrieval_status=None, url_contains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0006000" if __import__("os").path.isdir("./environment_mix/0006000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status, code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "DeepResearch",
            "endpoint": "list-sources",
            "status": status,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    if not isinstance(sessionId, str) or sessionId.strip() == "":
        _log("error", "VALIDATION_ERROR", "sessionId must be a non-empty string")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")

    allowed_status = {"discovered", "fetched", "fetch_failed"}
    if retrieval_status is not None:
        if not isinstance(retrieval_status, str) or retrieval_status not in allowed_status:
            _log("error", "VALIDATION_ERROR", "retrieval_status is invalid")
            return _err("VALIDATION_ERROR", "retrieval_status is invalid", allowed=sorted(list(allowed_status)))

    if url_contains is not None and (not isinstance(url_contains, str)):
        _log("error", "VALIDATION_ERROR", "url_contains must be a string")
        return _err("VALIDATION_ERROR", "url_contains must be a string")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 500:
        _log("error", "VALIDATION_ERROR", "limit must be an integer within [1, 500]")
        return _err("VALIDATION_ERROR", "limit must be an integer within [1, 500]")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("error", "VALIDATION_ERROR", "cursor must be a string")
            return _err("VALIDATION_ERROR", "cursor must be a string")
        # Opaque cursor: base64 of "offset:<n>"
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                _log("error", "VALIDATION_ERROR", "cursor is invalid")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("negative")
        except Exception:
            _log("error", "VALIDATION_ERROR", "cursor is invalid")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Load collections
    sessions = _load("research_sessions.json")
    sources = _load("sources.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(sources, list): sources = []

    # Ensure session exists
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break
    if sess is None:
        _log("error", "NOT_FOUND", "Session not found")
        return _err("NOT_FOUND", "Session not found")

    # Filter sources
    rows = [r for r in sources if isinstance(r, dict) and r.get("session_id") == sessionId]
    if retrieval_status is not None:
        rows = [r for r in rows if r.get("retrieval_status") == retrieval_status]
    if url_contains is not None:
        sub = url_contains.lower()
        rows = [r for r in rows if isinstance(r.get("url"), str) and sub in r["url"].lower()]

    # Sort: by relevance_score desc (null last), then created_at asc, then id
    def _score(v):
        x = v.get("relevance_score")
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        return None
    def _created(v):
        c = v.get("created_at")
        return c if isinstance(c, str) else ""
    rows.sort(key=lambda r: (-( _score(r) if _score(r) is not None else -1e18), _created(r), r.get("id") or ""))

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{start+limit}".encode("utf-8")).decode("utf-8")

    _log("ok")

    return {
        "sessionId": sessionId,
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }
